        raise NotImplementedError

    def put(self, key, value):
        raise NotImplementedError

    @property
    def stats(self):
        raise NotImplementedError

    def __len__(self):
        raise NotImplementedError

    def __contains__(self, key):
        raise NotImplementedError

    def __repr__(self):
        raise NotImplementedError
